  const viewportRef = useRef<HTMLElement | null>(null);
  const [toastMessage, setToastMessage] = useState<string | null>(null);

  useEffect(() => {
    const rootEl = viewportRef.current;
    if (!rootEl) return;

    const updateStickyNavbars = () => {
      const scrolled = (window.scrollY || window.pageYOffset || 0) > 10;
      const navs = rootEl.querySelectorAll<HTMLElement>('.dk-sticky-navbar, [data-dk-navbar="true"]');
      navs.forEach((nav) => {
        if (scrolled) nav.classList.add('dk-navbar-scrolled');
        else nav.classList.remove('dk-navbar-scrolled');
      });
    };

    const animTargets = rootEl.querySelectorAll<HTMLElement>('.dk-root-frame > *');
    animTargets.forEach((el, idx) => {
      if (el.classList.contains('dk-sticky-navbar')) return;
      el.style.setProperty('--dk-delay', `${Math.min(idx * 35, 420)}ms`);
      el.classList.add('dk-animate-in');
    });

    updateStickyNavbars();
    window.addEventListener('scroll', updateStickyNavbars, { passive: true });
    return () => {
      window.removeEventListener('scroll', updateStickyNavbars);
    };
  }, []);

  useEffect(() => {
    if (!toastMessage) return;
    const timer = window.setTimeout(() => setToastMessage(null), 2600);
    return () => window.clearTimeout(timer);
  }, [toastMessage]);

  const handleViewportClick = (e: React.MouseEvent<HTMLElement>) => {
    const target = e.target as HTMLElement | null;
    if (!target) return;

    const btn = target.closest<HTMLElement>('.dk-interactive-btn, button');
    if (btn) {
      const rect = btn.getBoundingClientRect();
      const ripple = document.createElement('span');
      ripple.className = 'dk-ripple-wave';
      ripple.style.left = `${e.clientX - rect.left}px`;
      ripple.style.top = `${e.clientY - rect.top}px`;
      btn.appendChild(ripple);
      window.setTimeout(() => ripple.remove(), 600);

      const label = (btn.getAttribute('data-dk-action') || btn.textContent || 'Action').trim();
      const targetSelector = btn.getAttribute('data-dk-target') || '';
      const scope = btn.closest('.dk-root-frame') || viewportRef.current;
      const inputs = scope ? Array.from(scope.querySelectorAll<HTMLInputElement | HTMLTextAreaElement>('input.dk-interactive-input, textarea.dk-interactive-input')) : [];
      const filled = inputs.map((i) => i.value.trim()).filter(Boolean);

      if (filled.length > 0 && /submit|send|subscribe|join|start|search|login|sign|book|continue|apply/i.test(label)) {
        setToastMessage(`✓ ${label}: ${filled.join(', ')}`);
        return;
      }

      if (targetSelector && targetSelector.startsWith('#') && targetSelector.length > 1) {
        const dest = document.querySelector(targetSelector);
        if (dest) {
          dest.scrollIntoView({ behavior: 'smooth', block: 'start' });
          return;
        }
      }
      setToastMessage(`✓ ${label}`);
      return;
    }

    const link = target.closest<HTMLAnchorElement>('a.dk-interactive-link');
    if (link) {
      const href = link.getAttribute('href') || '';
      if (href.startsWith('#')) {
        e.preventDefault();
        if (href === '#top' || href === '#') {
          window.scrollTo({ top: 0, behavior: 'smooth' });
        } else {
          const section = document.querySelector(href);
          if (section) section.scrollIntoView({ behavior: 'smooth', block: 'start' });
          else setToastMessage(`Navigating to ${(link.textContent || href).trim()}`);
        }
      }
    }
  };

